def to_roman(number):
    """Roman numeral for an int from 1 to 3999."""
    if isinstance(number, bool) or not isinstance(number, int) or not 1 <= number <= 3999:
        raise ValueError("number must be an integer from 1 to 3999")

    values = (
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
    )
    result = []
    for value, symbol in values:
        count, number = divmod(number, value)
        result.append(symbol * count)
    return "".join(result)


def from_roman(text):
    """The int for a standard Roman numeral."""
    if not isinstance(text, str) or not text:
        raise ValueError("text must be a standard Roman numeral")

    values = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    if any(character not in values for character in text):
        raise ValueError("text must be a standard Roman numeral")

    total = 0
    for index, character in enumerate(text):
        value = values[character]
        if index + 1 < len(text) and value < values[text[index + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999 or to_roman(total) != text:
        raise ValueError("text must be a standard Roman numeral")
    return total
